insert into public.occasion_playbooks(id,occasion,display_name,dress_codes,priorities,styling_guidance,shopping_guidance,cultural_note,source_urls,sort_order) values
('birthday','Birthday','Birthday','{"Celebration","Smart casual","Expressive"}','{"photos","confidence","comfort","budget"}','Choose one expressive focal piece, build around a comfortable base, and check shoes against venue and walking. Offer a more understated alternative as well as a bolder option.','Use the owned wardrobe first. If a gap remains, shop one high-impact piece that works with at least three existing garments. Never assume a new outfit is required.','Ask about host preferences, venue, age-appropriateness if relevant, and cultural context rather than inferring these.','{"https://extension.usu.edu/research/principles-of-design","https://doi.org/10.1371/journal.pone.0102772"}',10),
('graduation','Graduation','Graduation','{"Smart celebratory","Polished","Ceremony appropriate"}','{"gown compatibility","photos","walking","weather"}','Check gown or institutional requirements first. Avoid bulky sleeves or collars that conflict with the gown; consider shoes for standing, walking and stairs. Provide an after-ceremony layer option.','Prefer rewearable smart pieces. Only suggest a purchase when the user lacks a practical ceremony-ready item; avoid buying a whole outfit for a short event.','Institutional and family expectations vary; ask rather than assuming a universal graduation dress code.','{"https://extension.usu.edu/research/principles-of-design"}',20),
('wedding-guest','Wedding guest','Wedding guest','{"Ceremony appropriate","Formal","Smart celebratory"}','{"invitation dress code","venue","comfort","cultural expectations"}','Invitation and couple guidance outrank generic styling rules. Do not suggest white/bridal-looking clothing when inappropriate; ask if colour restrictions are unclear.','Suggest rewearing a suitable base with a new accessory before recommending a new dress or suit. Never claim an item is appropriate without the event guidance.','Wedding traditions and colour meanings differ; ask about culture, ceremony and stated restrictions.','{"https://extension.usu.edu/research/principles-of-design"}',30),
('date-night','Date night','Date night','{"Smart casual","Formal","Casual"}','{"confidence","venue","comfort","personal taste"}','Anchor the look to the venue and the user’s chosen mood. Offer one familiar option and one expressive option; do not assume gender or relationship context.','Check whether an owned outfit already works. If shopping, prioritize versatile items with repeat use over a one-event purchase.','Never infer the user’s gender, body type, relationship or desired level of exposure.','{"https://doi.org/10.1145/3702327","https://doi.org/10.1371/journal.pone.0102772"}',40),
('campus-event','Campus event','Campus event','{"Expressive casual","Smart casual","Comfort-first"}','{"budget","walking","weather","self-expression"}','Build from owned basics and add a personal focal piece. Account for walking, sitting, transport and weather where data is available.','Prefer low-cost gaps only after checking existing pieces. Consider borrowing or re-styling before recommending a purchase.','Do not assume campus culture or event rules; use user-provided dress requirements.','{"https://www.unep.org/resources/other/sustainability-and-circularity-textile-value-chain-global-roadmap"}',50),
('job-interview','Job interview','Job interview','{"Polished","Smart casual","Formal"}','{"industry norms","cleanliness","comfort","practicality"}','Match formality to employer, role, and interview format. Keep distracting accessories optional; prioritize fit, comfort and neatness over trend conformity.','Recommend a new item only when a material gap exists and budget permits; prioritize pieces reusable at work and interviews.','Professional dress norms can encode cultural and economic bias. Do not treat one aesthetic as a measure of competence.','{"https://extension.usu.edu/research/principles-of-design"}',60),
('dinner','Dinner','Dinner','{"Venue-led","Smart casual","Formal"}','{"venue","comfort","occasion","budget"}','Ask or use the venue type to set formality. Keep shoes practical for travel and walking.','Reuse a known outfit; if a gap exists, prefer an item that works across several occasions.','Do not assume dinner is romantic, formal or alcohol-related.','{"https://doi.org/10.1371/journal.pone.0102772"}',70),
('family-celebration','Family celebration','Family celebration','{"Personal and occasion-aware","Smart celebratory","Modest and polished"}','{"comfort","family context","movement","budget"}','Ask about traditions, formality, mobility and personal preferences. Offer comfortable and more dressed-up options.','Check existing pieces and accessories before recommending purchases.','Family, religious and cultural expectations are user-specific; never infer them from location alone.','{"https://extension.usu.edu/research/principles-of-design"}',80),
('church-ceremony','Church or faith ceremony','Church or faith ceremony','{"Modest and polished","Ceremony appropriate","Formal"}','{"stated dress guidance","comfort","movement","weather"}','Follow the venue’s stated dress guidance and user’s own modesty preferences. Make coverage adjustments only when requested or relevant to explicit requirements.','Suggest simple, rewearable pieces; do not frame modesty as a universal requirement.','Faith traditions and personal practice vary substantially; ask, do not assume.','{"https://extension.usu.edu/research/principles-of-design"}',90),
('workday','Workday','Workday','{"Smart casual","Polished","Comfort-first"}','{"role","commute","comfort","repeat wear"}','Match role and workplace dress expectations. Prioritize comfortable layers, useful pockets and shoes for commute.','Use cost-per-wear reasoning and versatile additions; avoid implying frequent new purchases are necessary.','Workplace norms vary; use the user’s description.','{"https://www.unep.org/resources/other/sustainability-and-circularity-textile-value-chain-global-roadmap"}',100),
('travel','Travel day','Travel day','{"Comfort-first","Casual","Smart casual"}','{"movement","temperature","layers","packing"}','Use breathable layers, shoes suitable for walking and practical combinations. Consider climate at destination only when location and weather data are available.','Prioritize versatile garments already owned. Recommend new travel gear only for a clear functional need.','Never claim live weather or route conditions without a connected data source.','{"https://www.whering.co/"}',110),
('outdoor-event','Outdoor event','Outdoor event','{"Casual","Smart casual","Celebration"}','{"weather","terrain","movement","sun/rain protection"}','Consider venue surface, walking, temperature, wind and precipitation when verified weather data exists.','Look for multipurpose layers and suitable footwear; do not invent forecast details.','Ask about access and mobility needs if the user wants practical adjustments.','{"https://www.whering.co/"}',120),
('date-campus','Campus date','Campus date','{"Casual","Smart casual","Expressive"}','{"comfort","budget","personal style"}','Combine campus-appropriate comfort with the user’s chosen mood; avoid gendered outfit assumptions.','Use existing wardrobe first; if shopping, suggest versatile pieces that fill a documented gap.','Do not infer gender, body type or relationship goals.','{"https://doi.org/10.1145/3702327"}',130),
('gym','Gym or active','Gym or active','{"Activewear","Comfort-first"}','{"movement","fabric","weather","activity"}','Use garments intended for the activity and movement. Do not recommend restrictive or unsuitable clothing based on appearance alone.','Prioritize function, durability, washability and fit. Avoid recommending fashion-only purchases for a performance need.','Ask about activity and accessibility needs when relevant.','{"https://www.unep.org/resources/other/sustainability-and-circularity-textile-value-chain-global-roadmap"}',140),
('interview-online','Online interview','Online interview','{"Polished","Smart casual"}','{"camera framing","comfort","lighting"}','Prioritize the visible upper half while keeping the full outfit comfortable. Avoid unsupported claims that a colour is universally best on camera.','Check owned shirts, tops and layers first. Only suggest a purchase if there is a real gap.','Do not assume interview platform or employer expectations.','{"https://extension.usu.edu/research/principles-of-design"}',150),
('date-formal','Formal event','Formal event','{"Formal","Black tie if explicitly requested"}','{"invitation","fit","comfort","reuse"}','Follow the actual dress code. Never label an event black tie unless the invitation says so. Offer borrowing/rental/re-wear as alternatives.','Prioritize re-use, borrowing or rental before a costly one-off purchase where available.','Dress codes and availability differ by region and budget; avoid assumptions.','{"https://www.unep.org/resources/other/sustainability-and-circularity-textile-value-chain-global-roadmap"}',160)
insert into public.shopping_gap_guides(id,occasion,category,when_to_consider,alternatives,budget_guidance,source_urls) values
('birthday-shoes','Birthday','Shoes','Only if the available footwear is unsuitable for venue, walking or stated dress code.','Clean existing shoes; borrow; choose a versatile pair wearable to campus and dinner.','Set a hard budget; never use the full budget just because it exists.','{"https://www.shopzetu.com/"}'),
('birthday-top','Birthday','Tops','Only if no available top works with owned bottoms and dress code.','Re-style an existing shirt, tee or blouse with accessories and layering.','Prefer one focal item that creates at least three outfits.','{"https://www.shopzetu.com/","https://doi.org/10.1371/journal.pone.0102772"}'),
('birthday-accessories','Birthday','Accessories','When an accessory adds a clear focal point and works with existing garments.','Use owned jewellery, belt, scarf, bag or hairstyle; no accessory is mandatory.','Low-cost add-ons should not crowd out transport, food or other event needs.','{"https://extension.usu.edu/research/principles-of-design"}'),
('graduation-shoes','Graduation','Shoes','When walking, standing, gown fit or ceremony rules make existing shoes impractical.','Use clean comfortable shoes already owned; test walking and standing first.','Avoid a single-use purchase if the existing pair is safe and appropriate.','{"https://extension.usu.edu/research/principles-of-design"}'),
('graduation-layer','Graduation','Outerwear','When weather, travel or after-ceremony plans require a layer.','Borrow or use a neutral layer that works over other outfits.','Budget for versatility and weather needs, not just ceremony photos.','{"https://www.whering.co/"}'),
('wedding-guest-shoes','Wedding guest','Shoes','When venue terrain, dress code or comfort makes current shoes unsuitable.','Clean versatile shoes; consider heel height and walking surface.','Do not assume a high heel or new shoe is required.','{"https://extension.usu.edu/research/principles-of-design"}'),
('wedding-guest-accessories','Wedding guest','Accessories','Only when an accessory supports the invitation’s dress code and does not conflict with restrictions.','Use existing neutral or occasion-appropriate accessories.','Prioritize re-wear and respect the couple’s instructions.','{"https://extension.usu.edu/research/principles-of-design"}'),
('date-night-top','Date night','Tops','When there is no available top suited to the venue and the chosen style.','Re-style an existing top with an open layer, tuck, belt or accessory if comfortable.','Buy for repeat wear rather than a single date.','{"https://www.shopzetu.com/"}'),
('date-night-bag','Date night','Bags','When a practical carry option is needed for the venue.','Use an owned bag that safely fits essentials.','A new bag is optional, not a default recommendation.','{"https://www.shopzetu.com/"}'),
('campus-shoes','Campus event','Shoes','When current shoes are uncomfortable or unsuited to walking/weather.','Clean and re-style existing sneakers or flats.','Function and durability usually matter more than event-only trends.','{"https://www.shopzetu.com/"}'),
('campus-layer','Campus event','Outerwear','When forecast or venue makes a layer useful.','Use a jacket, overshirt or sweater already owned.','Buy only if it will be used across multiple days.','{"https://www.whering.co/"}'),
('interview-shirt','Job interview','Tops','When no clean, comfortable option meets the employer’s stated expectations.','Use an existing shirt/top, ensure it is clean, and test it on camera if remote.','Choose a rewearable basic; avoid debt or overspending for one interview.','{"https://www.shopzetu.com/"}'),
('interview-shoes','Job interview','Shoes','When existing shoes are damaged or incompatible with stated dress expectations.','Clean, repair or borrow appropriate shoes if possible.','Prioritize fit and function over brand status.','{"https://www.shopzetu.com/"}'),
('dinner-layer','Dinner','Outerwear','When the venue or verified forecast suggests a layer is useful.','Use an existing jacket or overshirt.','Choose an item that works for work, travel and everyday use.','{"https://www.whering.co/"}'),
('family-celebration-accessories','Family celebration','Accessories','When the user wants a personal or culturally meaningful detail.','Use existing accessories; ask the user about traditions rather than assuming.','No purchase is required to respect or express cultural identity.','{"https://extension.usu.edu/research/principles-of-design"}'),
('travel-layer','Travel day','Outerwear','When destination conditions and itinerary justify a layer.','Pack a layer already owned and re-wear across outfits.','Prefer light, versatile pieces to duplicate single-purpose garments.','{"https://www.whering.co/"}'),
('outdoor-rain-layer','Outdoor event','Outerwear','When a verified forecast indicates rain or the event requires weather protection.','Use an owned rain layer or borrow one.','Do not recommend a purchase from a forecast unless weather is actually available.','{"https://www.whering.co/"}'),
('gym-activewear','Gym or active','Activewear','When current clothes impede movement or are unsuitable for the activity.','Use existing comfortable garments if safe and suitable.','Function, comfort and washability before fashion branding.','{"https://www.unep.org/resources/other/sustainability-and-circularity-textile-value-chain-global-roadmap"}'),
('formal-event-shoes','Formal event','Shoes','When the invitation and venue genuinely require a different shoe.','Borrow, rent where available, or use an appropriate versatile pair.','Avoid an expensive one-event purchase without checking alternatives.','{"https://www.shopzetu.com/"}'),
('workday-bag','Workday','Bags','When commute or role requires secure, practical carry.','Use an existing bag that meets capacity and safety needs.','Durability and repeat use are better signals than trend alone.','{"https://www.shopzetu.com/"}')
