-- LOOKU's research-backed occasion library and non-invented shopping gap logic.
-- Public content is readable by authenticated and anonymous clients; only trusted maintainers seed/update it.
create table if not exists public.occasion_playbooks (
  id text primary key,
  occasion text not null,
  display_name text not null,
  dress_codes text[] not null default '{}',
  priorities text[] not null default '{}',
  styling_guidance text not null,
  shopping_guidance text not null,
  cultural_note text not null default '',
  source_urls text[] not null default '{}',
  sort_order integer not null default 100,
  updated_at timestamptz not null default now()
);
create table if not exists public.shopping_gap_guides (
  id text primary key,
  occasion text not null,
  category text not null,
  when_to_consider text not null,
  alternatives text not null,
  budget_guidance text not null,
  source_urls text[] not null default '{}',
  updated_at timestamptz not null default now()
);
alter table public.occasion_playbooks enable row level security;
alter table public.shopping_gap_guides enable row level security;
drop policy if exists "Public can read occasion playbooks" on public.occasion_playbooks;
create policy "Public can read occasion playbooks" on public.occasion_playbooks for select to anon, authenticated using (true);
drop policy if exists "Public can read shopping gap guides" on public.shopping_gap_guides;
create policy "Public can read shopping gap guides" on public.shopping_gap_guides for select to anon, authenticated using (true);
revoke insert, update, delete, truncate, references, trigger on public.occasion_playbooks from anon, authenticated;
revoke insert, update, delete, truncate, references, trigger on public.shopping_gap_guides from anon, authenticated;

on conflict (id) do update set occasion=excluded.occasion,display_name=excluded.display_name,dress_codes=excluded.dress_codes,priorities=excluded.priorities,styling_guidance=excluded.styling_guidance,shopping_guidance=excluded.shopping_guidance,cultural_note=excluded.cultural_note,source_urls=excluded.source_urls,sort_order=excluded.sort_order,updated_at=now();

on conflict (id) do update set occasion=excluded.occasion,category=excluded.category,when_to_consider=excluded.when_to_consider,alternatives=excluded.alternatives,budget_guidance=excluded.budget_guidance,source_urls=excluded.source_urls,updated_at=now();
